@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

/*
 * Command Noir — a keyboard-first command-palette / launcher aesthetic.
 *
 * Built from a dark launcher overlay: a near-black stage, a slightly lifted
 * palette body, crisp list rows that light up with a single cool accent when
 * selected, hairline separators between sections, light keycap chips, and a
 * tight mono-leaning type voice. Depth is communicated with thin rims and a
 * soft cool glow, never heavy drop shadows — the palette floats, it does not
 * cast a thick blur.
 *
 * Core ideas:
 *   - Monochrome near-black surfaces, each step ~+0.04 L lighter.
 *   - One cool steel accent (--primary) carries selection + filled controls.
 *   - Selected rows use a faint translucent accent wash, not a solid block.
 *   - 0.0313rem hairline rims at low white alpha keep edges sharp on near-black.
 *   - Inputs sit in a shallow recessed well; controls + buttons share one
 *     accent material (solid fill + cool rim + soft glow), scaled by size.
 */

:root {
  /* ─── Surfaces (deepest → highest) ─── */
  --background: oklch(0.145 0.004 250);        /* near-black stage */
  --foreground: oklch(0.97 0.003 250);         /* crisp near-white text */

  --card: oklch(0.185 0.005 252);              /* palette body */
  --card-foreground: oklch(0.97 0.003 250);

  --popover: oklch(0.205 0.006 252);           /* floating menus / results */
  --popover-foreground: oklch(0.97 0.003 250);

  /* ─── Primary: the one cool accent that carries selection ─── */
  --primary: oklch(0.56 0.142 248);            /* deep steel-blue accent */
  --primary-foreground: oklch(0.985 0.006 240); /* white label on the deep fill */

  --secondary: oklch(0.225 0.006 252);         /* keycap / chip surface */
  --secondary-foreground: oklch(0.82 0.004 250);

  --muted: oklch(0.205 0.006 252);
  --muted-foreground: oklch(0.62 0.006 250);   /* dim section labels */

  --accent: oklch(0.255 0.012 240);            /* selected-row wash */
  --accent-foreground: oklch(0.97 0.003 250);

  --destructive: oklch(0.62 0.2 22);
  --destructive-foreground: oklch(0.98 0.003 250);
  --success: oklch(0.62 0.15 150);
  --success-foreground: oklch(0.145 0.004 250);
  --warning: oklch(0.76 0.15 75);
  --warning-foreground: oklch(0.145 0.004 250);

  --border: oklch(1 0 0 / 0.07);               /* hairline separators */
  --input: oklch(0.17 0.005 252);              /* recessed field well */
  --ring: oklch(0.7 0.122 233 / 0.55);
  --radius: 0.5rem;                            /* 0.5rem — small, precise */

  /*
   * ─── Shadow & material scale ───
   * Floating surfaces use a hairline rim + a soft, low-spread shadow so the
   * palette reads as a thin pane of glass, not a thick card. The accent
   * material (--accent-fill) is the shared skin for the primary button and
   * every filled control (checkbox / switch / radio / slider range).
   */

  /* Floating surface elevations — rim + soft ambient, no heavy blur */
  --shadow-xs:
    0 0 0 0.0313rem oklch(1 0 0 / 0.05),
    0 0.0625rem 0.125rem oklch(0 0 0 / 0.4);

  --shadow-sm:
    0 0 0 0.0313rem oklch(1 0 0 / 0.06),
    0 0.125rem 0.375rem oklch(0 0 0 / 0.45);

  --shadow-md:
    0 0 0 0.0313rem oklch(1 0 0 / 0.07),
    0 0.375rem 1.125rem oklch(0 0 0 / 0.5);

  --shadow-lg:
    0 0 0 0.0313rem oklch(1 0 0 / 0.08),
    0 0.875rem 2.25rem oklch(0 0 0 / 0.55);

  --shadow-xl:
    0 0 0 0.0313rem oklch(1 0 0 / 0.09),
    0 1.5rem 3.75rem oklch(0 0 0 / 0.62);

  /* Recessed well — shallow top inset, faint bottom edge highlight */
  --shadow-well:
    inset 0 0.0625rem 0.0625rem oklch(0 0 0 / 0.5),
    inset 0 -0.0625rem 0 oklch(1 0 0 / 0.03);

  --shadow-well-deep:
    inset 0 0.0625rem 0.125rem oklch(0 0 0 / 0.6),
    inset 0 -0.0625rem 0 oklch(1 0 0 / 0.04);

  /* Accent material — the shared skin for primary button + filled controls.
     Solid accent fill, cool rim, faint top highlight, soft cool outer glow. */
  --accent-fill: linear-gradient(180deg, oklch(0.58 0.146 248) 0%, oklch(0.5 0.142 248) 100%);
  --accent-fill-hover: linear-gradient(180deg, oklch(0.62 0.15 248) 0%, oklch(0.54 0.146 248) 100%);
  --shadow-accent:
    0 0 0 0.0313rem oklch(0.78 0.13 233 / 0.7),
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.2),
    0 0.0625rem 0.1875rem oklch(0 0 0 / 0.5),
    0 0 0.75rem oklch(0.7 0.122 233 / 0.28);
  --shadow-accent-hover:
    0 0 0 0.0313rem oklch(0.82 0.13 233 / 0.85),
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.24),
    0 0.125rem 0.3125rem oklch(0 0 0 / 0.55),
    0 0 1.125rem oklch(0.7 0.122 233 / 0.38);

  /*
   * ─── Legacy aliases ───
   * The 90+ shadcn primitives reference --shadow-s/-m/-l and a few specialised
   * tokens. Mapped to the Command Noir recipe so each primitive inherits the
   * theme without being touched individually.
   */
  --shadow-s: var(--shadow-sm);
  --shadow-m: var(--shadow-md);
  --shadow-l: var(--shadow-lg);
  --shadow-inset: var(--shadow-well);
  --shadow-inset-deep: var(--shadow-well-deep);
  --shadow-button: var(--shadow-accent);
  --shadow-button-hover: var(--shadow-accent-hover);
  --shadow-primary: var(--shadow-accent);
  --shadow-pill: var(--shadow-accent);
  --shadow-pill-hover: var(--shadow-accent-hover);
  --pill-gradient: var(--accent-fill);
  --pill-gradient-hover: var(--accent-fill-hover);
  --text-shadow-pressed: 0 0.0625rem 0 oklch(0 0 0 / 0.35);

  /* ─── Chart palette: tonal ramp of the DS primary (one hue, five shades) ─── */
  --chart-1: var(--primary);
  --chart-2: oklch(from var(--primary) calc(l - 0.09) calc(c * 0.92) h);
  --chart-3: oklch(from var(--primary) calc(l - 0.18) calc(c * 0.84) h);
  --chart-4: oklch(from var(--primary) calc(l - 0.27) calc(c * 0.76) h);
  --chart-5: oklch(from var(--primary) calc(l - 0.36) calc(c * 0.68) h);

  /* --- Motion (crisp profile) ---
     Bare transition-* and ease-* classes read these; durations are
     duration-fast, duration-base and duration-slow once installed. */
  --transition-duration-fast: 120ms;
  --transition-duration-base: 160ms;
  --transition-duration-slow: 220ms;
  --ease-out: cubic-bezier(0.25, 0.46, 0.45, 0.94);
  --ease-in-out: cubic-bezier(0.455, 0.03, 0.515, 0.955);
  --ease-in: cubic-bezier(0.55, 0.085, 0.68, 0.53);
  --default-transition-duration: var(--transition-duration-fast);
  --default-transition-timing-function: var(--ease-out);

  /* AI parts: the label that marks what a model wrote. */
  --ai-label: var(--muted);
  --ai-label-foreground: var(--foreground);
}

/* Registers duration-fast, duration-base and duration-slow, which the
   components use. `reference` writes no variable that points at itself. */
@theme inline reference {
  --transition-duration-fast: var(--transition-duration-fast);
  --transition-duration-base: var(--transition-duration-base);
  --transition-duration-slow: var(--transition-duration-slow);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-success: var(--success);
  --color-success-foreground: var(--success-foreground);
  --color-warning: var(--warning);
  --color-warning-foreground: var(--warning-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --radius-sm: calc(var(--radius) - 0.25rem);
  --radius-md: calc(var(--radius) - 0.125rem);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 0.25rem);

  --shadow-s: var(--shadow-s);
  --shadow-m: var(--shadow-m);
  --shadow-l: var(--shadow-l);
  --shadow-inset: var(--shadow-inset);
  --shadow-inset-deep: var(--shadow-inset-deep);
  --shadow-button: var(--shadow-button);
  --shadow-button-hover: var(--shadow-button-hover);
  --shadow-primary: var(--shadow-primary);
  --shadow-pill: var(--shadow-pill);
  --shadow-pill-hover: var(--shadow-pill-hover);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);

}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground antialiased;
    font-family: var(--font-geist-mono), "Geist Mono", ui-monospace, "SF Mono",
      "Fira Code", "Roboto Mono", "Menlo", "Consolas", monospace;
    letter-spacing: -0.005em;
  }

  ::selection {
    background-color: var(--primary);
    color: var(--primary-foreground);
  }
  /* stylelint-disable-next-line selector-no-vendor-prefix */
  ::-moz-selection {
    background-color: var(--primary);
    color: var(--primary-foreground);
  }

  /* Let textareas grow with their content instead of nested scrolling:
     smoother writing, easier-to-scan forms. */
  textarea {
    /* Fallback for browsers without field-sizing (e.g. Firefox): keep the
       textarea user-resizable so it can still be grown manually. */
    resize: vertical;
  }
  @supports (field-sizing: content) {
    textarea {
      field-sizing: content;
      max-height: 20lh;
      overflow-y: auto;
    }
  }

  /* Reserve the scrollbar gutter so the page keeps its width whenever the
     scrollbar comes and goes: content loading in, moving between a short
     and a tall page, or a scroll lock that just hides overflow. */
  html {
    scrollbar-gutter: stable;
  }
  @supports (scrollbar-gutter: stable) {
    html body[data-scroll-locked] {
      /* Radix's scroll lock re-adds the scrollbar width as body margin. The
         stable gutter already reserves it, so without this the two stack and
         opening a dialog shifts the page the other way. */
      margin-right: 0 !important;
    }
  }
}

@layer utilities {
  /* Show an invalid field on the field itself, not only in the message under
     it. Declared after Tailwind's utilities, so it wins over the field's own
     border and focus-ring classes. */
  [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]),
  [role="radiogroup"][aria-invalid="true"] [role="radio"] {
    border-color: var(--destructive);
  }
  [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]):focus-visible,
  [role="radiogroup"][aria-invalid="true"] [role="radio"]:focus-visible {
    border-color: var(--destructive);
    --tw-ring-color: color-mix(in oklch, var(--destructive) 35%, transparent);
  }

  /* Shake a field once when it turns invalid. */
  @keyframes deny-shake {
    25% { translate: -0.09375rem; }
    50% { translate: 0.109375rem; }
    75% { translate: -0.109375rem; }
  }
  @media (prefers-reduced-motion: no-preference) {
    [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]),
    [role="radiogroup"][aria-invalid="true"] [role="radio"],
    [data-input-otp-container]:has([aria-invalid="true"]) {
      animation: deny-shake 250ms linear;
    }
  }
}

:root {
  --layout-density: compact;
  --layout-density-source: design-system;
  --layout-sidebar: calc(var(--spacing, 0.25rem) * 46);
  --layout-inset: calc(var(--spacing, 0.25rem) * 4);
  --layout-section-gap: calc(var(--spacing, 0.25rem) * 6);
  --layout-column-gap: calc(var(--spacing, 0.25rem) * 3);
  --layout-card-padding: calc(var(--spacing, 0.25rem) * 4);
}

